-- Actualización para una base Prisma ya instalada. No modifica existencias.
begin;
do $$ begin
 if to_regclass('public.prisma_members') is null or to_regprocedure('public.prisma_authorize()') is null then raise exception 'Primero ejecuta supabase/setup.sql completo para instalar la base inicial.';end if;
end $$;
create table if not exists public.prisma_preparations(id bigint generated by default as identity primary key,date date not null,folio text not null,np text not null,start_time text not null,end_time text not null,end_next_day boolean not null default false,minutes numeric not null,requested_date date,requested_time text,supplies text not null,product text not null,notes text not null default '');
alter table public.prisma_preparations enable row level security;
revoke all on public.prisma_preparations from anon,authenticated;
create or replace function public.prisma_save_preparation(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
<<prep>>
declare b jsonb:=payload;d date;requested date;initial_time text;final_time text;requested_time text;next_day boolean;duration numeric;record_id bigint;
begin
 perform public.prisma_authorize();perform pg_advisory_xact_lock(104202611);
 if coalesce(b->>'date','') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Fecha no válida.';end if;
 d:=(b->>'date')::date;if d>public.prisma_today() then raise exception 'No se permiten preparaciones con fecha futura.';end if;
 initial_time:=b->>'start_time';final_time:=b->>'end_time';requested_time:=nullif(b->>'requested_time','');
 if coalesce(initial_time,'') !~ '^([01]\d|2[0-3]):[0-5]\d(:[0-5]\d)?$' or coalesce(final_time,'') !~ '^([01]\d|2[0-3]):[0-5]\d(:[0-5]\d)?$' then raise exception 'Horas de inicio o fin no válidas.';end if;
 if requested_time is not null and requested_time !~ '^([01]\d|2[0-3]):[0-5]\d(:[0-5]\d)?$' then raise exception 'Hora solicitada no válida.';end if;
 next_day:=coalesce((b->>'end_next_day')::boolean,false);
 duration:=extract(epoch from (final_time::time-initial_time::time))+(case when next_day then 86400 else 0 end);
 if duration<0 then raise exception 'La hora de fin es anterior al inicio. Indica si terminó al día siguiente.';end if;
 if duration>86400 then raise exception 'La preparación no puede superar 24 horas.';end if;
 duration:=round(duration/60,2);
 if nullif(b->>'requested_date','') is not null and b->>'requested_date' !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Fecha solicitada no válida.';end if;
 requested:=nullif(b->>'requested_date','')::date;
 if coalesce(btrim(b->>'folio'),'')='' or coalesce(btrim(b->>'np'),'')='' or coalesce(btrim(b->>'supplies'),'')='' or coalesce(btrim(b->>'product'),'')='' then raise exception 'Faltan orden, NP, insumos o producto.';end if;
 record_id:=nullif(b->>'id','')::bigint;
 if record_id is null then
  insert into public.prisma_preparations(date,folio,np,start_time,end_time,end_next_day,minutes,requested_date,requested_time,supplies,product,notes) values(d,b->>'folio',b->>'np',initial_time,final_time,next_day,duration,requested,requested_time,b->>'supplies',b->>'product',coalesce(b->>'notes','')) returning id into record_id;
 else
  update public.prisma_preparations set date=d,folio=b->>'folio',np=b->>'np',start_time=initial_time,end_time=final_time,end_next_day=next_day,minutes=duration,requested_date=requested,requested_time=prep.requested_time,supplies=b->>'supplies',product=b->>'product',notes=coalesce(b->>'notes','') where id=record_id;
  if not found then raise exception 'Registro de preparación no encontrado.';end if;
 end if;
 return jsonb_build_object('ok',true,'id',record_id);
end $$;
revoke all on function public.prisma_save_preparation(jsonb) from public,anon,authenticated;
grant execute on function public.prisma_save_preparation(jsonb) to authenticated;

create table if not exists public.prisma_incidents(id bigint generated by default as identity primary key,incident_number integer not null unique,date date not null,order_id bigint not null references public.prisma_orders(id),order_ref text not null,np text not null default '',machine text not null,description text not null,responsible text not null,action text not null default '',impact text not null,status text not null,prepared_by text not null default '',color_observed text not null default '',test_result text not null default '',validation_notes text not null default '',request_key text unique);
alter table public.prisma_incidents enable row level security;
revoke all on public.prisma_incidents from anon,authenticated;
alter table public.prisma_incidents add column if not exists timer_mode boolean not null default false;
alter table public.prisma_incidents add column if not exists started_at timestamptz;
alter table public.prisma_incidents add column if not exists ended_at timestamptz;
alter table public.prisma_incidents add column if not exists before_photo text;
alter table public.prisma_incidents add column if not exists after_photo text;
create or replace function public.prisma_check_incident_photo(value text) returns void language plpgsql set search_path=public,pg_temp as $$
begin
 if value is null or value='' then return;end if;
 if length(value)>450000 or value !~ '^data:image/jpeg;base64,[A-Za-z0-9+/]+=*$' then raise exception 'Foto JPEG no válida o demasiado grande.';end if;
 if substring(decode(split_part(value,',',2),'base64') from 1 for 3)<>decode('ffd8ff','hex') then raise exception 'La foto no contiene un JPEG válido.';end if;
end $$;
create or replace function public.prisma_start_incident(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare b jsonb:=payload;old public.prisma_incidents%rowtype;o public.prisma_orders%rowtype;n integer;record_id bigint;start_time timestamptz:=clock_timestamp();np_value text;key text;
begin
 perform public.prisma_authorize();perform pg_advisory_xact_lock(104202611);
 key:=nullif(b->>'request_key','');
 if key is not null then select * into old from public.prisma_incidents where request_key=key;if found then
  if old.order_id is distinct from (b->>'order_id')::bigint or not old.timer_mode then raise exception 'La captura ya está vinculada a otro registro.';end if;
  return jsonb_build_object('ok',true,'id',old.id,'folio','INC-'||lpad(old.incident_number::text,greatest(4,length(old.incident_number::text)),'0'),'started_at',old.started_at);
 end if;end if;
 select * into o from public.prisma_orders where id=(b->>'order_id')::bigint;if not found then raise exception 'Selecciona una orden registrada.';end if;
 select coalesce(max(incident_number),10)+1 into n from public.prisma_incidents;
 select case when count(distinct np)=1 then min(np) else '' end into np_value from public.prisma_items where order_id=o.id and np<>'';
 insert into public.prisma_incidents(incident_number,date,order_id,order_ref,np,machine,description,responsible,impact,status,request_key,timer_mode,started_at) values(n,public.prisma_today(),o.id,o.folio,coalesce(np_value,''),'','Registro en curso','','','Abierta',key,true,start_time) returning id into record_id;
 return jsonb_build_object('ok',true,'id',record_id,'folio','INC-'||lpad(n::text,greatest(4,length(n::text)),'0'),'started_at',start_time);
end $$;
create or replace function public.prisma_update_timed_incident(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare b jsonb:=payload;r public.prisma_incidents%rowtype;finish boolean;before_value text;after_value text;ending timestamptz;np_value text;machine_value text;responsible_value text;impact_value text;
begin
 perform public.prisma_authorize();perform pg_advisory_xact_lock(104202611);
 select * into r from public.prisma_incidents where id=(b->>'id')::bigint;if not found or not r.timer_mode then raise exception 'Cronómetro no encontrado.';end if;
 if r.order_id is distinct from (b->>'order_id')::bigint then raise exception 'No se puede cambiar la orden del cronómetro.';end if;
 finish:=coalesce((b->>'finish')::boolean,false) or r.ended_at is not null;
 before_value:=case when b?'before_photo' then b->>'before_photo' else r.before_photo end;after_value:=case when b?'after_photo' then b->>'after_photo' else r.after_photo end;
 perform public.prisma_check_incident_photo(before_value);perform public.prisma_check_incident_photo(after_value);
 if finish and (coalesce(before_value,'')='' or coalesce(after_value,'')='') then raise exception 'Agrega la foto del defecto y la foto final.';end if;
 machine_value:=coalesce(b->>'machine',r.machine);responsible_value:=coalesce(b->>'responsible',r.responsible);impact_value:=coalesce(b->>'impact',r.impact);np_value:=coalesce(b->>'np',r.np);
 if machine_value<>'' and machine_value not in ('Mark Andy','Comco 1','Comco 2','Maquina China') then raise exception 'Máquina no válida.';end if;
 if responsible_value<>'' and responsible_value not in ('Diseño','Producción','Preprensa','Proveedor','Mantenimiento','Compartida') then raise exception 'Responsable no válido.';end if;
 if impact_value<>'' and impact_value not in ('Merma','Paro','Retrabajo','Calidad','Entrega','Otro') then raise exception 'Impacto no válido.';end if;
 if np_value<>'' and not exists(select 1 from public.prisma_items where order_id=r.order_id and np=np_value) then raise exception 'NP no válido.';end if;
 ending:=coalesce(r.ended_at,case when finish then clock_timestamp() else null end);
 update public.prisma_incidents set np=np_value,machine=machine_value,responsible=responsible_value,impact=impact_value,description=coalesce(nullif(b->>'description',''),r.description),action=coalesce(nullif(b->>'action',''),case when finish then 'Corrección documentada en fotografía final.' else r.action end),status=case when finish then 'Cerrada' else 'Abierta' end,prepared_by=coalesce(b->>'prepared_by',r.prepared_by),color_observed=coalesce(b->>'color_observed',r.color_observed),test_result=coalesce(b->>'test_result',r.test_result),validation_notes=coalesce(b->>'validation_notes',r.validation_notes),before_photo=before_value,after_photo=after_value,ended_at=ending where id=r.id;
 return jsonb_build_object('ok',true,'id',r.id,'folio','INC-'||lpad(r.incident_number::text,greatest(4,length(r.incident_number::text)),'0'),'started_at',r.started_at,'ended_at',ending);
end $$;
create or replace function public.prisma_incident_evidence(record_id bigint) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare result jsonb;
begin
 perform public.prisma_authorize();
 select jsonb_build_object('id',i.id,'before_photo',i.before_photo,'after_photo',i.after_photo) into result from public.prisma_incidents i where i.id=record_id;
 if result is null then raise exception 'Incidencia no encontrada.';end if;return result;
end $$;
revoke all on function public.prisma_check_incident_photo(text),public.prisma_update_timed_incident(jsonb),public.prisma_start_incident(jsonb),public.prisma_incident_evidence(bigint) from public,anon,authenticated;
grant execute on function public.prisma_start_incident(jsonb),public.prisma_incident_evidence(bigint) to authenticated;

create or replace function public.prisma_save_incident(payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
<<inc>>
declare b jsonb:=payload;d date;oid bigint;ref text;record_id bigint;folio_number integer;np_value text;key text;
begin
 perform public.prisma_authorize();perform pg_advisory_xact_lock(104202611);
 key:=nullif(b->>'request_key','');record_id:=nullif(b->>'id','')::bigint;
 if record_id is not null and exists(select 1 from public.prisma_incidents where id=record_id and timer_mode) then return public.prisma_update_timed_incident(b);end if;
 if key is not null and record_id is null then
  select id,incident_number into record_id,folio_number from public.prisma_incidents where request_key=key;
  if found then return jsonb_build_object('ok',true,'id',record_id,'folio','INC-'||lpad(folio_number::text,greatest(4,length(folio_number::text)),'0'));end if;
 end if;
 if coalesce(b->>'date','') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Fecha no válida.';end if;
 d:=(b->>'date')::date;if d>public.prisma_today() then raise exception 'No se permiten incidencias con fecha futura.';end if;
 oid:=nullif(b->>'order_id','')::bigint;select folio into ref from public.prisma_orders where id=oid;if not found then raise exception 'Selecciona una orden de producción registrada.';end if;
 np_value:=coalesce(b->>'np','');if np_value<>'' and not exists(select 1 from public.prisma_items where order_id=oid and np=np_value) then raise exception 'El NP no pertenece a esa orden.';end if;
 if b->>'machine' is null or b->>'machine' not in ('Mark Andy','Comco 1','Comco 2','Maquina China') then raise exception 'Máquina no válida.';end if;
 if b->>'responsible' is null or b->>'responsible' not in ('Diseño','Producción','Preprensa','Proveedor','Mantenimiento','Compartida') then raise exception 'Responsable no válido.';end if;
 if b->>'impact' is null or b->>'impact' not in ('Merma','Paro','Retrabajo','Calidad','Entrega','Otro') then raise exception 'Impacto no válido.';end if;
 if b->>'status' is null or b->>'status' not in ('Abierta','En seguimiento','Cerrada') then raise exception 'Estatus no válido.';end if;
 if coalesce(btrim(b->>'description'),'')='' then raise exception 'Describe la incidencia.';end if;
 if b->>'status'='Cerrada' and coalesce(btrim(b->>'action'),'')='' then raise exception 'Captura la acción realizada antes de cerrar la incidencia.';end if;
 if record_id is null then
  select coalesce(max(incident_number),10)+1 into folio_number from public.prisma_incidents;
  insert into public.prisma_incidents(incident_number,date,order_id,order_ref,np,machine,description,responsible,action,impact,status,prepared_by,color_observed,test_result,validation_notes,request_key) values(folio_number,d,oid,ref,np_value,b->>'machine',b->>'description',b->>'responsible',coalesce(b->>'action',''),b->>'impact',b->>'status',coalesce(b->>'prepared_by',''),coalesce(b->>'color_observed',''),coalesce(b->>'test_result',''),coalesce(b->>'validation_notes',''),key) returning id into record_id;
 else
  update public.prisma_incidents set date=d,order_id=oid,order_ref=ref,np=np_value,machine=b->>'machine',description=b->>'description',responsible=b->>'responsible',action=coalesce(b->>'action',''),impact=b->>'impact',status=b->>'status',prepared_by=coalesce(b->>'prepared_by',''),color_observed=coalesce(b->>'color_observed',''),test_result=coalesce(b->>'test_result',''),validation_notes=coalesce(b->>'validation_notes','') where id=record_id returning incident_number into folio_number;
  if not found then raise exception 'Incidencia no encontrada.';end if;
 end if;
 return jsonb_build_object('ok',true,'id',record_id,'folio','INC-'||lpad(folio_number::text,greatest(4,length(folio_number::text)),'0'));
end $$;
revoke all on function public.prisma_save_incident(jsonb) from public,anon,authenticated;
grant execute on function public.prisma_save_incident(jsonb) to authenticated;

create or replace function public.prisma_state() returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
begin
 perform public.prisma_authorize();
 return jsonb_build_object('today',public.prisma_today(),'baseline',(select value from public.prisma_metadata where key='baseline'),
 'incidents',coalesce((select jsonb_agg((to_jsonb(r)-'before_photo'-'after_photo')||jsonb_build_object('has_before',coalesce(r.before_photo,'')<>'','has_after',coalesce(r.after_photo,'')<>'','elapsed_seconds',case when r.started_at is null then 0 else greatest(0,floor(extract(epoch from (coalesce(r.ended_at,now())-r.started_at)))) end,'folio','INC-'||lpad(r.incident_number::text,greatest(4,length(r.incident_number::text)),'0')) order by r.incident_number desc) from public.prisma_incidents r),'[]'::jsonb),
 'preparations',coalesce((select jsonb_agg(to_jsonb(r) order by r.date desc,r.start_time desc,r.id desc) from public.prisma_preparations r),'[]'::jsonb),
 'products',coalesce((select jsonb_agg(to_jsonb(p) order by name) from public.prisma_products p),'[]'::jsonb),
 'lots',coalesce((select jsonb_agg(to_jsonb(x) order by x.name,x.entry_date) from (select l.*,p.name,p.code,p.kind,p.provider,p.category,p.minimum,p.maximum,p.container_grams from public.prisma_lots l join public.prisma_products p on p.id=l.product_id)x),'[]'::jsonb),
 'movements',coalesce((select jsonb_agg(to_jsonb(x) order by x.date desc,x.id desc) from (select m.*,p.name,p.code,l.lot from public.prisma_movements m join public.prisma_lots l on l.id=m.lot_id join public.prisma_products p on p.id=l.product_id)x),'[]'::jsonb),
 'orders',coalesce((select jsonb_agg(to_jsonb(o)||jsonb_build_object('lines',coalesce((select jsonb_agg(to_jsonb(x) order by x.id) from (select i.*,p.name,p.code,l.lot from public.prisma_items i join public.prisma_lots l on l.id=i.lot_id join public.prisma_products p on p.id=l.product_id where i.order_id=o.id)x),'[]'::jsonb)) order by o.date desc,o.id desc) from public.prisma_orders o),'[]'::jsonb),
 'cuts',coalesce((select jsonb_agg(to_jsonb(c) order by month desc) from public.prisma_cuts c),'[]'::jsonb));
end $$;


revoke all on function public.prisma_state() from public,anon,authenticated;
grant execute on function public.prisma_state() to authenticated;
notify pgrst, 'reload schema';
commit;
